<?php require __DIR__.'/includes/db.php'; require __DIR__.'/includes/auth.php'; require_login(); $id=(int)($_GET['id']??$_POST['id']??0);$s=$pdo->prepare('SELECT * FROM students WHERE id=?');$s->execute([$id]);$student=$s->fetch();if(!$student)exit('Student not found');if($_SERVER['REQUEST_METHOD']==='POST'){$u=$pdo->prepare('UPDATE students SET name=?,roll_number=?,email=?,course=? WHERE id=?');$u->execute([trim($_POST['name']),trim($_POST['roll_number']),trim($_POST['email']),trim($_POST['course']),$id]);header('Location: student_detail.php?id='.$id);exit;} ?><!doctype html><meta charset="utf-8"><link rel="stylesheet" href="admin.css"><main class="main" style="margin:5vh auto;max-width:700px"><section class="table-card" style="padding:28px"><h1>Edit student</h1><form method="post" class="edit-form"><input type="hidden" name="id" value="<?=$id?>"><?php foreach(['name'=>'Full name','roll_number'=>'Roll number','email'=>'Email','course'=>'Course'] as $k=>$label):?><label><?=$label?><input name="<?=$k?>" value="<?=e($student[$k])?>" required></label><?php endforeach?><button class="add-btn">Update student</button> <a href="student_detail.php?id=<?=$id?>">Cancel</a></form></section></main><style>.edit-form label{display:block;margin:17px 0}.edit-form input{display:block;width:100%;padding:12px;border:1px solid #dce3ee;border-radius:7px;margin-top:7px}</style>
